#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long q;
    cin >> q;
    vector<vector<long long>> qs(q, vector<long long>(2));
    for (int i = 0; i < q; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> qs[i][j];
        }
    }

    for (long long t = 0; t < q; t++) {
        long long a = qs[t][0], b = qs[t][1];
        int k = __builtin_popcountll(b);
        long long x = 0;
        for (int bit = 61; bit >= 0; bit--) {
            if (k > 0 && ((a >> bit) & 1)) {
                x |= 1LL << bit;
                k--;
            }
        }
        for (int bit = 0; k > 0; bit++) {
            if (!((x >> bit) & 1)) {
                x |= 1LL << bit;
                k--;
            }
        }
        cout << (t ? " " : "") << x;
    }
    cout << "\n";

    return 0;
}

